-- Research catalog seed only. Existing rows, quantities, costs, and owner URLs preserved.
ON CONFLICT (sku) DO UPDATE SET
 supplier_url=CASE WHEN nullif(btrim(materials.supplier_url),'') IS NULL THEN excluded.supplier_url ELSE materials.supplier_url END,
 supplier_name=COALESCE(NULLIF(btrim(materials.supplier_name),''),excluded.supplier_name),
 notes=COALESCE(NULLIF(btrim(materials.notes),''),excluded.notes)
WHERE nullif(btrim(materials.supplier_url),'') IS NULL;
